package com.oguzguven.portfolio.message;import java.util.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/messages") public class ContactMessageController{private final ContactMessageService service;public ContactMessageController(ContactMessageService service){this.service=service;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ContactMessageResponse create(@Valid @RequestBody ContactMessageRequest request){return service.create(request);}@GetMapping public List<ContactMessageResponse> findAll(){return service.findAll();}@PatchMapping("/{id}/read")public ContactMessageResponse toggleRead(@PathVariable UUID id){return service.toggleRead(id);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id){service.delete(id);}}
